def transform(grid):
    pts=[(c,r) for r,row in enumerate(grid) for c,v in enumerate(row) if v==5]
    if len(pts)<3: return [row[:] for row in grid]
    pts=sorted(set(pts))
    def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    lo=[]
    for p in pts:
        while len(lo)>=2 and cross(lo[-2],lo[-1],p)<=0: lo.pop()
        lo.append(p)
    hi=[]
    for p in reversed(pts):
        while len(hi)>=2 and cross(hi[-2],hi[-1],p)<=0: hi.pop()
        hi.append(p)
    poly=lo[:-1]+hi[:-1]
    out=[row[:] for row in grid]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==5: continue
            inside=True
            for i,a in enumerate(poly):
                b=poly[(i+1)%len(poly)]
                if cross(a,b,(c,r))<0:
                    inside=False; break
            if inside: out[r][c]=3
    return out
