def transform(grid):
    out=[row[:] for row in grid]
    # Each marker row shades the span between its outermost markers.
    for r,row in enumerate(grid):
        marks=[c for c,v in enumerate(row) if v==5]
        if len(marks)>1:
            for c in range(marks[0]+1,marks[-1]):
                if row[c]!=5: out[r][c]=3
    return out
